// Client configuration composition for the native SDK constructor.
// Kept in sync with specs/providers/daytona.yaml client: rules (not emitted).

import type { DaytonaConfig as NativeClientConfig } from "@daytona/sdk";
import {
  ErrorKind,
  sandboxError,
  type Config,
  ConfigFieldAuth,
  ConfigFieldScopeAppName,
  ConfigFieldScopeEnvironment,
  ConfigFieldScopeProjectId
} from "@sandbox-kit/sandbox";
import {
  mapAPIKeyCredentials,
  mapBearerAuth,
  mapClientSettings,
  mapScope,
} from "#mappings/provider_mappings.js";

const defaultEndpoint = "https://app.daytona.io/api";

export function mapGeneratedClientConfig(config: Config): NativeClientConfig {
  const source: Config =
    config.endpoint === undefined
      ? { ...config, endpoint: defaultEndpoint }
      : config;
  const target: NativeClientConfig = mapClientSettings(source, "initialize");
  if (source.scope !== undefined) {
    const mapped = mapScope(source.scope, "initialize");
    Object.assign(target, mapped);
    if (source.scope.appName !== undefined)
      unsupported(ConfigFieldScopeAppName, "unsupported client configuration field");
    if (source.scope.environment !== undefined)
      unsupported(
        ConfigFieldScopeEnvironment,
        "unsupported client configuration field",
      );
    if (source.scope.projectId !== undefined)
      unsupported(ConfigFieldScopeProjectId, "unsupported client configuration field");
  }
  if (source.auth?.apiKey !== undefined) {
    Object.assign(
      target,
      mapAPIKeyCredentials(source.auth.apiKey, "initialize"),
    );
  } else if (source.auth?.bearerToken !== undefined) {
    Object.assign(
      target,
      mapBearerAuth(source.auth.bearerToken, "initialize"),
    );
  } else if (source.auth !== undefined) {
    unsupported(ConfigFieldAuth, "unsupported authentication mode");
  }
  return target;
}

function unsupported(field: string, message: string): never {
  throw sandboxError({
    kind: ErrorKind.Unsupported,
    provider: "daytona",
    operation: "initialize",
    field,
    message: "sandbox-kit daytona: " + message,
  });
}

// Client configuration composition for the native SDK constructor.
// Kept in sync with specs/providers/modal.yaml client: rules (not emitted).

import type { ModalClientParams as NativeClientConfig } from "modal";
import {
  ErrorKind,
  sandboxError,
  type Config,
  type Scope,
  ConfigFieldAuth,
  ConfigFieldEndpoint,
  ConfigFieldScopeProjectId
} from "@sandbox-kit/sandbox";
import {
  mapClientScope,
  mapOAuthAuth,
  mapTokenPairCredentials,
} from "#mappings/provider_mappings.js";

export function mapGeneratedClientConfig(config: Config): NativeClientConfig {
  const source = config;
  const target: NativeClientConfig = {};
  if (source.endpoint !== undefined)
    unsupported(
      ConfigFieldEndpoint,
      "Endpoint cannot be configured through this SDK's public client constructor",
    );
  if (source.scope !== undefined) {
    const mapped = mapClientScope(source.scope, "initialize");
    Object.assign(target, mapped);
    if (source.scope.organizationId !== undefined)
      unsupported(
        "scope.organizationId",
        "unsupported client configuration field",
      );
    if (source.scope.projectId !== undefined)
      unsupported(ConfigFieldScopeProjectId, "unsupported client configuration field");
  }
  if (source.auth?.tokenPair !== undefined) {
    Object.assign(
      target,
      mapTokenPairCredentials(source.auth.tokenPair, "initialize"),
    );
  } else if (source.auth?.oauthRefresh !== undefined) {
    Object.assign(
      target,
      mapOAuthAuth(source.auth.oauthRefresh, "initialize"),
    );
  } else if (source.auth !== undefined) {
    unsupported(ConfigFieldAuth, "unsupported authentication mode");
  }
  return target;
}

export interface ProviderState {
  readonly scope?: Scope;
  readonly region?: string;
}

export function captureProviderState(config: Config): ProviderState {
  return {
    ...(config.scope === undefined
      ? {}
      : { scope: structuredClone(config.scope) }),
    ...(config.region === undefined ? {} : { region: config.region }),
  };
}

function unsupported(field: string, message: string): never {
  throw sandboxError({
    kind: ErrorKind.Unsupported,
    provider: "modal",
    operation: "initialize",
    field,
    message: "sandbox-kit modal: " + message,
  });
}

